resolved=Monstey_NavSeamResolveCandidates(std::array{Candidate(0,1,2,.5f,.5f),Candidate(0,2,1,0,1)});Check(!resolved.front().enabled&&resolved.back().enabled,"Closed zero-length containment differs");++groups;
