a=Quad(pa);b=Quad(pb,2);std::array<std::uint8_t,6>leaf{};std::array<std::uint8_t,18>pair{};pair[3]=0x80;pair[4]=1;pair[16]=1;const Monstey_NavigationCompactTreeView ta{leaf,a.bounds};const auto run=[&](const auto&av,const auto&bv,const auto&tb,float tolerance){return Monstey_NavSeamMatchGroundMeshes(av,bv,a.bounds,b.bounds,ta,tb,up,tolerance,settings);};auto full=run(a.View(),b.View(),Monstey_NavigationCompactTreeView{pair,b.bounds},.01f);Check(full.coincident_connections==1&&full.connections==std::vector<Monstey_NavSeamConnection>{{0,0,0,0}},"Greedy first distinct B edge lost");pair[10]=1;pair[16]=0;full=run(a.View(),b.View(),Monstey_NavigationCompactTreeView{pair,b.bounds},.01f);Check(full.connections==std::vector<Monstey_NavSeamConnection>{{0,0,1,4}},"Tree-order greedy preference lost");++groups;
b=Quad(pb);moved=b.View();moved.transform[3][2]=.01f;full=run(a.View(),moved,Monstey_NavigationCompactTreeView{leaf,b.bounds},.01f);Check(full.coincident_connections==1,"Inclusive coincident tolerance rejected");moved.transform[3][2]=std::nextafter(.01f,std::numeric_limits<float>::infinity());full=run(a.View(),moved,Monstey_NavigationCompactTreeView{leaf,b.bounds},.01f);Check(full.coincident_connections==0,"Above coincident tolerance admitted");++groups;
